SELECT w->>'kind' as kind, round((w->>'x1')::numeric,2) as x1, round((w->>'y1')::numeric,2) as y1, round((w->>'x2')::numeric,2) as x2, round((w->>'y2')::numeric,2) as y2, round(abs((w->>'x2')::numeric - (w->>'x1')::numeric),3) as dx, round(abs((w->>'y2')::numeric - (w->>'y1')::numeric),3) as dy FROM tactical_scenes ts, jsonb_array_elements(ts.walls::jsonb) w WHERE ts.id = '557378d7-557c-45b7-bf3c-42c2f73840a0' AND w->>'kind' = 'window' ORDER BY (w->>'y1')::float;
